generated_pydough:
# Find the most recent year and the city that hosted events in that year
most_recent_hosting = city_record.CALCULATE(
    most_recent_year=MAX(hosting_cities.year)
).hosting_cities.WHERE(
    year == most_recent_year
).CALCULATE(
    city_id=host_city
).TOP_K(1, by=city_id.ASC())

prof_info_system = professors.WHERE(
    department.dept_name == "Computer Info. Systems"
).CALCULATE(
    professor_first_name=employee.emp_fname,
    professor_degree=prof_high_degree
)

lowest_balance_account_name = account.WHERE(
    HAS(checkings) & HAS(saving)
).CALCULATE(
    acc_name=name,
    total_combined_balance=SUM(checkings.balance) + SUM(saving.balance)
).TOP_K(1, by=total_combined_balance.ASC()).CALCULATE(acc_name=acc_name)

# Find the maximum individual order quantity across all order items
max_order_quantity = customers_and_addresses.CALCULATE(
    max_qty = MAX(customer.customer_order.order_item.order_quantity)
)

# Find all customers who made orders containing order items with the maximum quantity
result = max_order_quantity.customer.customer_order.WHERE(
    HAS(order_item.WHERE(order_quantity == max_qty)) == 1
).CALCULATE(
    customer_name = customer.customer_name
)

# Find organisations involved in grants with total amounts exceeding 6000
organisations_with_large_grants = organisation.WHERE(
    HAS(grant) == 1
).CALCULATE(
    organisation_id=organisation_id,
    organisation_details=organisation_details,
    total_grant_amount=SUM(grant.grant_amount)
).WHERE(
    total_grant_amount > 6000
).CALCULATE(
    organisation_id=organisation_id,
    organisation_details=organisation_details
)

# Calculate the average enrollment across all universities
avg_enrollment = university_basketball.CALCULATE(
    average_enrollment=AVG(universities.enrollment)
)

# Find universities with enrollment smaller than average and get their team names
result = avg_enrollment.universities.WHERE(
    enrollment < average_enrollment
).basketball_matches.CALCULATE(
    team_name=team_name
)

team_with_least_attendance_game = home_games.WHERE(
    year == 1980
).TOP_K(1, by=attendance.ASC()).SINGULAR().CALCULATE(
    team_name=team.name
)

# Count project staff who worked as leaders OR started before the specified date
result = tracking_grants_for_research.CALCULATE(
    staff_count = COUNT(
        project_staffs.WHERE(
            (CONTAINS(LOWER(staff_role.role_description), "leader")) |
            (date_from < "1989-04-24 23:51:54")
        )
    )
)

department_managers = staffs.WHERE(
    staff_department_assignment.job_title_code == "Department Manager"
).CALCULATE(
    staff_id=staff_id,
    staff_gender=staff_gender
)

artist_exhibition_counts = theme_gallery.artists.WHERE(
    HAS(exhibitions) == 1
).CALCULATE(
    artist_name=name,
    num_of_exhibitions=COUNT(exhibitions)
)

customer_with_most_orders = customer.WHERE(
    HAS(customer_order) == 1
).CALCULATE(
    customer_name=customer_name,
    order_count=COUNT(customer_order)
).TOP_K(1, by=(order_count.DESC(), customer_name.ASC()))

shared_addresses_line1 = address.WHERE(
    (HAS(student) == 1) & (HAS(teacher) == 1)
).CALCULATE(
    line_1_of_address=line_1
)

# Find people who are friends with both Dan and Alice
friends_of_both = personfriends.WHERE(
    ISIN(friend, ("Dan", "Alice"))
).PARTITION(name="person_groups", by=name).WHERE(
    NDISTINCT(personfriends.friend) == 2
).personfriends.person.CALCULATE(
    person_name=name,
    person_age=age
)

european_countries_with_manufacturers = country.WHERE(
    continent_join.continent == "europe"
).WHERE(
    COUNT(car_maker) >= 3
).CALCULATE(
    country_name=countryname
)

elimination_times = wrestlers.WHERE(
    days_held > 50
).eliminations.CALCULATE(
    Time=time
)

# Find body builders whose birthday contains "January" and get their total scores
january_bodybuilders_total = peoples.WHERE(
    CONTAINS(birth_date, "January")
).body_builders.CALCULATE(
    total_score = total
)

campus_with_most_degrees = degree.PARTITION(
    name="campus_groups", by=campus
).CALCULATE(
    campus_id=campus,
    total_degrees=SUM(degree.degrees)
).TOP_K(1, by=total_degrees.DESC()).CALCULATE(campus_id)

northridge_sf_campuses = campuse.WHERE(
    ((location == "Northridge") & (county == "Los Angeles")) |
    ((location == "San Francisco") & (county == "San Francisco"))
).CALCULATE(
    campus_name=campus
)

# Find airports visited by Robinson R-22 and calculate average total passengers
robinson_airports_avg = airport_aircraft.WHERE(
    aircraft.aircraft == "Robinson R-22"
).CALCULATE(
    avg_passengers = AVG(airport.total_passengers)
)

most_expensive_catalog_entry = product_catalog.catalog_content.TOP_K(
    1, by=price_in_dollars.DESC()
).CALCULATE(
    entry_name=catalog_entry_name
)

students_with_dogs_no_cats = students.WHERE(
    (HAS(has_pets.WHERE(pet.pettype == "dog")) == 1) &
    (HASNOT(has_pets.WHERE(pet.pettype == "cat")) == 1)
).has_pets.WHERE(
    pet.pettype == "dog"
).CALCULATE(
    fname=student.fname,
    age=student.age
)

member_with_most_events = members.WHERE(
    HAS(party_event) == 1
).CALCULATE(
    member_name=member_name,
    event_count=COUNT(party_event)
).TOP_K(1, by=event_count.DESC()).CALCULATE(
    member_name=member_name
)

# Find cities with lower March temperature than July temperature that have been host cities
result = cities.WHERE(
    HAS(temperatures) == 1
).temperatures.WHERE(
    mar < jul
).city.WHERE(
    HAS(hosting_cities) == 1
).CALCULATE(
    city_name=city,
    city_id=city_id
)

committees_with_party_delegates = elections.PARTITION(name="committee_groups", by=committee).CALCULATE(
    committee_name=committee,
    has_democratic_delegate=HAS(elections.WHERE(party == 'Democratic')) == 1,
    has_liberal_delegate=HAS(elections.WHERE(party == 'Liberal')) == 1
).WHERE(
    (has_democratic_delegate == True) & (has_liberal_delegate == True)
).CALCULATE(
    committee_name=committee_name
)

most_languages_continent = countries.PARTITION(
    name="continent_groups", by=(continent)
).CALCULATE(
    continent_name=continent,
    num_languages=NDISTINCT(countries.countrylanguages.language)
).TOP_K(1, by=num_languages.DESC())

# Find restaurants with the highest rating
highest_rated_restaurants = restaurant_1.CALCULATE(
    max_rating = MAX(restaurants.rating)
).restaurants.WHERE(
    rating == max_rating
).CALCULATE(
    restaurant_name = resname,
    restaurant_rating = rating
)

# Find service types that have both successful and failure event details
services_with_both_outcomes = service.WHERE(
    HAS(event) == 1
).PARTITION(name="service_types", by=service_type_code).WHERE(
    (COUNT(service.event.WHERE(CONTAINS(LOWER(event_details), "success"))) > 0) &
    (COUNT(service.event.WHERE(CONTAINS(LOWER(event_details), "fail"))) > 0)
).CALCULATE(
    service_type_code=service_type_code
)

# Find programs that broadcast in both morning and night, then get their unique owners
result = programs.WHERE(
    HAS(broadcasts.WHERE(time_of_day == "Morning")) &
    HAS(broadcasts.WHERE(time_of_day == "Night"))
).CALCULATE(
    program_owner = owner
).PARTITION(name="unique_owners", by=program_owner).CALCULATE(
    owner = program_owner
)
